() => {
  const links = document.querySelectorAll('a[href*="vegan-lasagna"]');
  return Array.from(links).slice(0, 10).map(a => ({text: a.textContent.trim().slice(0, 100), href: a.href}));
}

() => {
  const links = document.querySelectorAll('a');
  return Array.from(links)
    .filter(a => a.href && (a.href.includes('vegan-lasagna') || a.href.includes('recipe')))
    .slice(0, 20)
    .map(a => ({text: a.textContent.trim().slice(0, 80), href: a.href}));
}
